PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
IF Level <= 10 THEN
    PumpIn := TRUE;
ELSIF Level >= 90 THEN
    PumpIn := FALSE;
END_IF;
ValveOut := Level >= 90;
END_PROGRAM

