PROGRAM intersection
VAR_OUTPUT
  NS_G : BOOL;
  NS_Y : BOOL;
  NS_R : BOOL;
  EW_G : BOOL;
  EW_Y : BOOL;
  EW_R : BOOL;
END_VAR
VAR
  State : INT := 0;
  Green : TON;
  Yellow : TON;
  AllRed : TON;
END_VAR
Green(IN := (State = 0) OR (State = 3), PT := T#2s);
Yellow(IN := (State = 1) OR (State = 4), PT := T#1s);
AllRed(IN := (State = 2) OR (State = 5), PT := T#1s);
IF Green.Q THEN
  State := (State + 1) MOD 6;
END_IF;
IF Yellow.Q THEN
  State := (State + 1) MOD 6;
END_IF;
IF AllRed.Q THEN
  State := (State + 1) MOD 6;
END_IF;
NS_G := State = 0;
NS_Y := State = 1;
NS_R := (State = 2) OR (State = 3) OR (State = 4) OR (State = 5);
EW_G := State = 3;
EW_Y := State = 4;
EW_R := (State = 0) OR (State = 1) OR (State = 2) OR (State = 5);
END_PROGRAM

PROGRAM intersection
VAR_OUTPUT
  NS_G : BOOL;
  NS_Y : BOOL;
  NS_R : BOOL;
  EW_G : BOOL;
  EW_Y : BOOL;
  EW_R : BOOL;
  State : INT := 0;
END_VAR
VAR
  Green : TON;
  Yellow : TON;
  AllRed : TON;
END_VAR
Green(IN := (State = 0) OR (State = 3), PT := T#2s);
Yellow(IN := (State = 1) OR (State = 4), PT := T#1s);
AllRed(IN := (State = 2) OR (State = 5), PT := T#1s);
IF Green.Q THEN
  IF State = 0 THEN State := 1;
  ELSIF State = 3 THEN State := 4;
  END_IF;
ELSIF Yellow.Q THEN
  IF State = 1 THEN State := 2;
  ELSIF State = 4 THEN State := 5;
  END_IF;
ELSIF AllRed.Q THEN
  IF State = 2 THEN State := 3;
  ELSIF State = 5 THEN State := 0;
  END_IF;
END_IF;
NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
CASE State OF
  0: NS_G := TRUE; NS_R := FALSE;
  1: NS_Y := TRUE; NS_R := FALSE;
  3: EW_G := TRUE; EW_R := FALSE;
  4: EW_Y := TRUE; EW_R := FALSE;
END_CASE;
END_PROGRAM

PROGRAM intersection
VAR_OUTPUT
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
END_VAR
VAR
    State : INT := 0;
    t_green : TON;
    t_yellow : TON;
    t_allred : TON;
END_VAR
t_green(IN := (State = 0) OR (State = 3), PT := T#2s);
t_yellow(IN := (State = 1) OR (State = 4), PT := T#1s);
t_allred(IN := (State = 2) OR (State = 5), PT := T#1s);
CASE State OF
    0: IF t_green.Q THEN State := 1; END_IF;
    1: IF t_yellow.Q THEN State := 2; END_IF;
    2: IF t_allred.Q THEN State := 3; END_IF;
    3: IF t_green.Q THEN State := 4; END_IF;
    4: IF t_yellow.Q THEN State := 5; END_IF;
    5: IF t_allred.Q THEN State := 0; END_IF;
END_CASE;
NS_G := State = 0;
NS_Y := State = 1;
NS_R := NOT (State = 0 OR State = 1);
EW_G := State = 3;
EW_Y := State = 4;
EW_R := NOT (State = 3 OR State = 4);
END_PROGRAM

PROGRAM intersection
VAR_OUTPUT
  NS_G : BOOL;
  NS_Y : BOOL;
  NS_R : BOOL;
  EW_G : BOOL;
  EW_Y : BOOL;
  EW_R : BOOL;
END_VAR
VAR
  State : INT := 0;
  green_timer : TON;
  yellow_timer : TON;
  allred_timer : TON;
END_VAR
green_timer(IN := (State = 0) OR (State = 3), PT := T#2s);
yellow_timer(IN := (State = 1) OR (State = 4), PT := T#1s);
allred_timer(IN := (State = 2) OR (State = 5), PT := T#1s);
CASE State OF
  0: IF green_timer.Q THEN State := 1; END_IF;
  1: IF yellow_timer.Q THEN State := 2; END_IF;
  2: IF allred_timer.Q THEN State := 3; END_IF;
  3: IF green_timer.Q THEN State := 4; END_IF;
  4: IF yellow_timer.Q THEN State := 5; END_IF;
  5: IF allred_timer.Q THEN State := 0; END_IF;
END_CASE;
CASE State OF
  0: NS_G := TRUE;  NS_Y := FALSE; NS_R := FALSE; EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
  1: NS_G := FALSE; NS_Y := TRUE;  NS_R := FALSE; EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
  2: NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;  EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
  3: NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;  EW_G := TRUE;  EW_Y := FALSE; EW_R := FALSE;
  4: NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;  EW_G := FALSE; EW_Y := TRUE;  EW_R := FALSE;
  5: NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;  EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
ELSE
  NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;  EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;
END_PROGRAM

