  State := 0;
  FillValve := FALSE;
  Heater := FALSE;
  Agitator := FALSE;
  DrainValve := FALSE;
ELSE
  CASE State OF
    0:
      FillValve := FALSE;
      Heater := FALSE;
      Agitator := FALSE;
      DrainValve := FALSE;
      IF StartBatch THEN
        State := 1;
      END_IF;
    1:
      FillValve := Level < LVL_HIGH;
      Heater := FALSE;
      Agitator := FALSE;
      DrainValve := FALSE;
      IF Level >= LVL_HIGH THEN
        State := 2;
