      FillValve := FALSE;
      Heater := (Temp < TEMP_SET) AND (Level >= LIQ_MIN);
      Agitator := (Temp < TEMP_SET) AND (Level >= LIQ_MIN);
      DrainValve := FALSE;
      IF Temp >= TEMP_SET THEN
        State := 3;
      END_IF;
    3:
      FillValve := FALSE;
      Heater := Level >= LIQ_MIN;
      Agitator := Level >= LIQ_MIN;
      DrainValve := FALSE;
      IF ReactTimer.Q THEN
        State := 4;
      END_IF;
    4:
      FillValve := FALSE;
      Heater := FALSE;
      Agitator := FALSE;
      DrainValve := Level > LVL_LOW;
      IF Level <= LVL_LOW THEN
        State := 0;
      END_IF;
