PROGRAM pump_alt
VAR_INPUT
  Demand : BOOL;
  EStop : BOOL;
END_VAR
VAR_OUTPUT
  Pump1 : BOOL;
  Pump2 : BOOL;
END_VAR
VAR
  Lead : INT := 0;
  PrevDemand : BOOL;
END_VAR
IF (NOT Demand) AND PrevDemand THEN
  IF Lead = 0 THEN
    Lead := 1;
  ELSE
    Lead := 0;
  END_IF;
END_IF;
IF EStop AND Demand THEN
  IF Lead = 0 THEN
    Pump1 := TRUE;
    Pump2 := FALSE;
  ELSE
    Pump1 := FALSE;
    Pump2 := TRUE;
  END_IF;
ELSE
  Pump1 := FALSE;
  Pump2 := FALSE;
END_IF;
PrevDemand := Demand;
END_PROGRAM

