VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT := 0;
    PrevDemand : BOOL;
END_VAR
IF PrevDemand AND NOT Demand THEN
    IF Lead = 0 THEN
        Lead := 1;
    ELSE
        Lead := 0;
    END_IF;
END_IF;
PrevDemand := Demand;
Pump1 := Demand AND EStop AND (Lead = 0);
Pump2 := Demand AND EStop AND (Lead = 1);
END_PROGRAM

