  PrevTrigger : BOOL;
END_VAR
IF Reset THEN
  Count := 0;
  Done := FALSE;
ELSIF Trigger AND NOT PrevTrigger AND Count < 3 THEN
  Count := Count + 1;
  IF Count = 3 THEN
    Done := TRUE;
  END_IF;
END_IF;
PrevTrigger := Trigger;
END_PROGRAM

